    'timetable': () => formStart('This creates a simple balanced first draft you can edit.')+field('Subjects (comma-separated)','subjects',{type:'textarea',placeholder:'Mathematics, Physics, English, Chemistry',required:true,full:true})+field('Study time per day (hours)','hours',{type:'number',value:'3',min:1,max:16,step:0.5,required:true})+field('Start time','start',{type:'time',value:'17:00',required:true})+field('Minutes per session','session',{type:'number',value:'40',min:15,max:120,step:5,required:true})+formEnd('Make timetable'),
    'flashcards': () => `<div class="notice green"><strong>Private, session-only deck</strong>Cards you create here stay in the current page session and are not sent to an AI provider.</div><form id="flash-form" style="margin-top:16px"><div class="form-grid">${field('Question / front','front',{type:'textarea',placeholder:'What is photosynthesis?',required:true,full:true})}${field('Answer / back','back',{type:'textarea',placeholder:'The process plants use to convert light into chemical energy.',required:true,full:true})}</div><div class="form-actions"><button class="btn btn-primary" type="submit">Add card +</button><button class="btn" type="button" id="clear-deck">Clear deck</button></div></form><div id="flashcard-count" class="panel-sub" style="margin-top:16px">No cards yet. Add your first card.</div><div id="flashcard-stage" class="cards-stage"></div>`,
