    'case': () => formStart('Paste or type text, then choose the output case.')+field('Text to convert','source',{type:'textarea',placeholder:'Type or paste your text…',required:true,full:true})+field('Conversion style','style',{type:'select',options:[['upper','UPPERCASE'],['lower','lowercase'],['title','Title Case'],['sentence','Sentence case'],['alternating','aLtErNaTiNg CaSe'],['reverse','Reverse text']]})+formEnd('Convert text'),
    'tts': () => formStart('Your browser provides the voice engine; available voices depend on your device.')+field('Text to read aloud','tts-text',{type:'textarea',placeholder:'Paste text here…',required:true,full:true})+field('Voice','tts-voice',{type:'select',options:[['default','Default device voice']]})+field('Speed','tts-rate',{type:'number',value:'1',min:0.5,max:2,step:0.1})+`</div><div class="form-actions"><button class="btn btn-primary" type="button" id="speak-btn">Speak ▶</button><button class="btn" type="button" id="stop-speech">Stop</button></div></form><div id="voice-note" class="notice blue" style="margin-top:16px">Loading available voices…</div>`,
