    'pdf-tools': () => `<form id="tool-form"><div class="form-grid">${field('Action','pdf-action',{type:'select',options:[['merge','Merge selected PDFs'],['split','Extract selected pages from one PDF']]})}<div class="field full"><label for="pdf-files">PDF file(s)</label><input type="file" id="pdf-files" accept="application/pdf,.pdf" multiple required><span class="hint">Merge: select 2 or more files. Split: select one file.</span></div>${field('Page ranges (split only)','page-ranges',{placeholder:'Example: 1,3-5',hint:'Use page numbers and ranges such as 1,3-5.'})}</div><div class="form-actions"><button class="btn btn-primary" type="submit">Process PDF files ↗</button><button class="btn" type="reset">Reset</button></div></form>${resultPanel()}<div class="notice blue" style="margin-top:15px">PDF files are processed in your browser by the PDF library. Large documents may use substantial memory.</div>`,
