    'code-format': () => formStart('Basic indentation helper. Always review output; this is not a full language parser.')+field('Code input','code-input',{type:'textarea',placeholder:'Paste HTML, CSS or JavaScript…',required:true,full:true})+field('Language','code-language',{type:'select',options:[['html','HTML'],['css','CSS'],['js','JavaScript']]})+formEnd('Format code'),
    'prompt-builder': () => formStart('Combine the fields into a clear prompt. This works locally and does not call an AI model.')+field('Role / perspective','prompt-role',{placeholder:'You are an experienced teacher…'})+field('Goal / task','prompt-goal',{type:'textarea',placeholder:'Explain how a solar eclipse happens…',required:true,full:true})+field('Context / audience','prompt-context',{placeholder:'Class 10 students, simple English'})+field('Tone / style','prompt-style',{placeholder:'Clear, friendly, step-by-step'})+field('Output format','prompt-format',{placeholder:'Numbered steps with an example'})+field('Constraints','prompt-constraints',{placeholder:'Stay under 300 words; define key terms'})+formEnd('Build prompt'),
    'text-animation': () => `<div class="text-animation-studio"><p class="panel-sub">Create a heading animation and export the CSS. Preview runs in your browser.</p><form id="text-animation-form"><div class="field full"><label for="ta-text">Text to animate</label><textarea id="ta-text" maxlength=240 placeholder="Dream bigger. Create better." required>MODEL AI — Create Without Limits</textarea></div><div class="form-grid"><div class="field"><label for="ta-preset">Animation style</label><select id="ta-preset"><option value="glow">Gold / blue glow</option><option value="fade">Soft fade up</option><option value="float">Floating</option><option value="bounce">Bounce</option><option value="typewriter">Typewriter</option><option value="gradient">Gradient shimmer</option></select></div><div class="field"><label for="ta-color">Text color</label><input id="ta-color" type="color" value="#4f62f6"></div><div class="field"><label for="ta-duration">Animation duration (seconds)</label><input id="ta-duration" type="number" min="0.5" max="8" step="0.1" value="2"></div><div class="field"><label for="ta-size">Text size (px)</label><input id="ta-size" type="number" min="16" max="80" value="38"></div></div><div class="form-actions"><button class="btn btn-primary" id="ta-replay" type="button">Replay animation ↻</button><button class="btn" id="ta-copy-css" type="button">Copy CSS</button><button class="btn" id="ta-download-css" type="button">Download CSS</button></div></form><section class="text-animation-preview-wrap"><span class="section-kicker">LIVE PREVIEW</span><div id="ta-preview" class="text-animation-preview glow">MODEL AI — Create Without Limits</div></section><div class="field full" style="margin-top:14px"><label for="ta-css-output">Generated CSS</label><textarea id="ta-css-output" class="code-output" readonly rows="10"></textarea></div></div>`,
