  // AI calls and secure multimodal chat
  async function apiCall(messages, options={}){
    const response = await fetch('/api/chat', {
      method:'POST', headers:{'Content-Type':'application/json'},
      body:JSON.stringify({messages, webSearch: options.webSearch === true}),
      signal:options.signal
    });
    let data;
    try { data = await response.json(); }
    catch { throw new Error(`Server returned HTTP ${response.status}. The function may not be deployed correctly.`); }
    if(!response.ok) throw new Error([data.error || `AI request failed (HTTP ${response.status}).`, data.details].filter(Boolean).join(' '));
    if(typeof data.text !== 'string' || !data.text.trim()) throw new Error('No text response was returned by the provider.');
    return data;
  }
